export async function getAppClientId(slug: string): Promise<string | null> {
  const app = await prisma.app.findUnique({
    where: { slug },
    select: { keys: true },
  });

  if (!app?.keys || typeof app.keys !== "object" || Array.isArray(app.keys)) return null;

  const clientId = app.keys.client_id;
  if (typeof clientId !== "string") return null;
  return clientId;
}
```

